tr_bt_hai_phia.code:
import sys

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
canh = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(m)]
from collections import deque
ke = [[] for _ in range(n + 1)]
for u, v in canh:
    ke[u].append(v)
    ke[v].append(u)
mau = [-1] * (n + 1)
ok = True
for s in range(1, n + 1):
    if mau[s] != -1:
        continue
    mau[s] = 1 if s > 1 else 0
    q = deque([s])
    while q:
        u = q.popleft()
        for v in ke[u]:
            if mau[v] == -1:
                mau[v] = 1 - mau[u]
                q.append(v)
            elif mau[v] == mau[u]:
                ok = False
if ok:
    print('co')
    print(*mau[1:])
else:
    print('khong')

